// Actions/private-bus HTTP boundary: explicit native READ and local history are
// separate. Stored roster completeness is not SDK or unknown-WRITE permission.
fn roster_http_config(root:&str)->serde_json::Value{let mut c=org_relation_http_config(root);c["profile"]["native_receivers"]["im_messages"]["directory_queries"]=serde_json::json!(true);c["profile"]["relation_events"]=serde_json::json!({"group_updates":true});c["profile"]["relation_roster"]=serde_json::json!({"observe":true});c}
fn roster_read_body()->serde_json::Value{serde_json::json!({"expected_revision":1,"operation":"relations","group_id":null,"since":"-1","consent":true})}
#[tokio::test]async fn roster_http_requires_auth_and_strict_finite_projection_without_permission_injection(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let base="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/relation-roster";for(method,path,body)in[(reqwest::Method::GET,base.to_owned(),None),(reqwest::Method::POST,format!("{base}/read"),Some(roster_read_body()))]{let(status,_,body)=account_request(&served,method,&path,body,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);}let cookie=authenticate(&served).await;for suffix in ["?limit=0","?limit=129","?limit=1&token=private","?limit=1&clear_gap=true"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{base}{suffix}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}for extra in ["uid","token","complete","result","clear_unknown"]{let mut input=roster_read_body();input[extra]=serde_json::json!(true);let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/read"),Some(input),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());}
#[tokio::test]async fn roster_http_policy_needs_original_event_consumers_and_directory_read_independently(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let good=roster_http_config(&cert.root);for mode in 0..5{let mut c=good.clone();match mode{0=>c["profile"]["relation_events"]=serde_json::Value::Null,1=>c["profile"]["org_relation_sync"]=serde_json::Value::Null,2=>c["profile"]["native_receivers"]["im_messages"]["directory_queries"]=serde_json::json!(false),3=>c["profile"]["relation_roster"]=serde_json::json!({"observe":false}),_=>c["profile"]["relation_roster"]=serde_json::json!({"observe":true,"write":true})}let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let base=format!("/api/non-3gpp/accounts/{line}/relation-roster");let(status,headers,body)=account_request(&served,reqwest::Method::GET,&base,None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");}
#[tokio::test]async fn roster_http_read_requires_consent_revision_current_run_and_canonical_since_not_properties(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":roster_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);for(mode,wanted)in [(0,StatusCode::FORBIDDEN),(1,StatusCode::CONFLICT),(2,StatusCode::SERVICE_UNAVAILABLE),(3,StatusCode::BAD_REQUEST),(4,StatusCode::BAD_REQUEST)]{let mut input=roster_read_body();match mode{0=>input["consent"]=serde_json::json!(false),1=>input["expected_revision"]=serde_json::json!(2),3=>input["since"]=serde_json::json!("01"),4=>input["operation"]=serde_json::json!("properties"),_=>{}}let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/relation-roster/read"),Some(input),Some(&cookie)).await;assert_eq!(status,wanted);no_store(&headers);no_secrets(&body);}assert!(state.app.app_accounts.relation_write_history(&line,128).unwrap().is_empty());}
#[tokio::test]async fn roster_http_saved_snapshot_reports_historical_completeness_never_exports_private_member_or_live_grant(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":roster_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);state.app.database.with_conn(|c|{c.execute("INSERT INTO app_voice_relation_rosters(line_id,revision,identity_key,receipt_epoch,target_key,target_kind,serial,baseline_time,observed_time,target_time,complete,gap,full_required,updated_at) VALUES(?1,1,zeroblob(32),?2,zeroblob(32),'buddy',1,?3,?4,?4,1,0,0,'2026-01-01T00:00:00Z')",rusqlite::params![line,"a".repeat(32),i64::MIN,i64::MAX]).map_err(|_|"fixture")?;let id=c.last_insert_rowid();c.execute("INSERT INTO app_voice_relation_roster_members(roster_id,label_key,relation) VALUES(?1,zeroblob(32),?2)",rusqlite::params![id,b"private-member".as_slice()]).map_err(|_|"fixture")}).unwrap();let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-roster?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);let d:serde_json::Value=serde_json::from_str(&body).unwrap();let row=&d["data"][0];assert_eq!(row["historical_complete"],true);assert_eq!(row["members"],1);assert_eq!(row["baseline_time"],"-9223372036854775808");assert_eq!(row["observed_time"],"9223372036854775807");for k in ["private-member","label_key","identity_key","receipt_epoch","token","grant","ready"]{assert!(!body.contains(k));}assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");}
